Item.method_code:
/*
　必要資料・テスト結果共通
  ・マルQの承認時に配下の必要資料を承認する
　・必要資料の承認時に配下のテスト結果を承認する。
*/

//マルQページの承認時にそのマルQページの必要資料で承認・再編集、却下、やるやらが×以外のものは承認にする
using (CCO.Permissions.GrantIdentity(Aras.Server.Security.Identity.GetByName("Aras PLM")))
{
    Innovator inn = this.getInnovator();
    //引数取得デバッグ用
    string applovedItem = this.getProperty("applovedItem");
    string destination = this.getProperty("destination");
    string sorceItemId = this.getProperty("sorceItemID");//必要資料の場合、マルＱ　テスト結果の場合必要資料
    
    var targets = new List<Item>();//承認対象集約
    
    if(applovedItem == "h4_ReqDoc")
    {
        //必要資料一覧取得
        var relItems = inn.newItem("h4_MQPage ReqDoc", "get");
        relItems.setProperty("source_id", sorceItemId);//マルQ
        relItems.setAttribute("select","related_id");
        relItems = relItems.apply();
        if(relItems.isError() && relItems.getItemCount() == -1)
        {
            //エラー
            // h4 ログ出力を入れる
            return inn.newError(CCO.ErrorLookup.Lookup("h4_S_E_0002"));
        }
    
        for(int i = 0; relItems.getItemCount() > i; i++)
        {
            string curReqDocID = relItems.getItemByIndex(i).getProperty("related_id","");
            Item curReqDoc = inn.newItem(applovedItem, "get");
            curReqDoc.setAttribute("select", "id,state,h4_yryr");
            curReqDoc.setID(curReqDocID);
            curReqDoc = curReqDoc.apply();
            if(curReqDoc.isError())
            {
                //エラー
                // h4 ログ出力を入れる
                return inn.newError(CCO.ErrorLookup.Lookup("h4_S_E_0002"));
            }  
            
            string tmp1state = curReqDoc.getProperty("state","");//カレントステートだとIdが来る
            var tmp1yryr = curReqDoc.getProperty("h4_yryr","");
        
            if(tmp1state == "Approved" || tmp1state == "Unapproved")//承認とリワークと却下とやるやら×を除外
            {
                continue;
            }
            targets.Add(curReqDoc);
        }
    }
    else if(applovedItem == "h4_Test_Result")
    {
        //必要資料-テスト結果
        // ソースに紐づいているアイテムを全取得
        Item relItems = inn.newItem("h4_ReqDoc TestResult", "get");
        relItems.setAttribute("select", "related_id");
        relItems.setProperty("source_id", sorceItemId);
        relItems = relItems.apply();

        for (int k = 0; k<relItems.getItemCount(); k++)
        {
            var tmp1ID = relItems.getItemByIndex(k).getProperty("related_id","");
            
            var tmp1 = inn.newItem("h4_Test_Result","get");
            tmp1.setID(tmp1ID);
            tmp1.setAttribute("select","id,h4_parent,state");
            tmp1 = tmp1.apply();
            if(tmp1.isError() || tmp1.getItemCount() != 1)
            {
                // h4 ログ出力を入れる
                return inn.newError(CCO.ErrorLookup.Lookup("h4_S_E_0002"));
            }

            // 親必要資料が該当するもののみ承認する
            if(tmp1.getProperty("h4_parent","") != sorceItemId)
            {
                continue;
            }
            
            string tmp1state = tmp1.getProperty("state","");//カレントステートだとIdが来る
            if(tmp1state == "Approved")
            {
                continue;
            }
            
            targets.Add(tmp1);
        }
    }

    //プロモート
    foreach (Item itm2 in targets){
        // サーバーメソッドでList変更したらStateを変える処理が入ってるのでそれにのっかる
        Item setTargetItem = inn.newItem(applovedItem,"edit");
        setTargetItem.setID(itm2.getID());
        setTargetItem.setAttribute("version","0");
        setTargetItem.setProperty("h4_directaplist",destination);//マルQと必要資料とテスト結果で同名
        setTargetItem = setTargetItem.apply();
    }
    
    return this;
}
